/// <summary>
/// Returns the carried code of the order
/// </summary>
public TMSCarrierCode getCarrierCode()
{
    TMSCarrierCode carrierCode;

    if(this.TableId == tableNum(SalesTable))
    {
        carrierCode = TMSSalesTable::find(this.OrderId).CarrierCode;
    }
    else if(this.TableId == tableNum(InventTransferTable))
    {
        carrierCode = TMSInventTransferTable::find(this.OrderId).CarrierCode;
    }

    return carrierCode;
}

public CustAccount getCustomerAccount()
{
    CustAccount custAccount;

    if(this.TableId == tableNum(SalesTable))
    {
        custAccount = this.CustomerAccount;
    }
    else if(this.TableId == tableNum(InventTransferTable))
    {
        custAccount = METInventLocation::findByInventLocationId(this.InventLocationTo).InternalCustomer;
    }

    return custAccount;
}

/// <summary>
/// Returns the extension tables
/// </summary>
public METOrderSplitGroup getOrderSplitGroup()
{
    METOrderSplitGroup splitGroup;

    if(this.TableId == tableNum(SalesTable))
    {
        splitGroup = METSalesTable::findByRefRecId(this.RecId).OrderSplitGroup;
    }
    else if(this.TableId == tableNum(InventTransferTable))
    {
        splitGroup = METInventTransferTableExt::findByTransferId(this.OrderId).OrderSplitGroup;
    }

    return splitGroup;
}

/// <summary>
/// Returns the extension tables
/// </summary>
public Common getExtensionTable()
{
    Common extensionTable;

    if(this.TableId == tableNum(SalesTable))
    {
        extensionTable = METSalesTable::findByRefRecId(this.RecId);
    }
    else if(this.TableId == tableNum(InventTransferTable))
    {
        extensionTable = METInventTransferTableExt::findByTransferId(this.OrderId);
    }

    return extensionTable;
}

public METTMSShipmentID getShipmentID()
{
    str     shippingDateStr;

    shippingDateStr = date2Str
        (this.ConfirmedShipDate,
            321,
            DateDay::Digits2,
            DateSeparator::None,
            DateMonth::Digits2,
            DateSeparator::None,
            DateYear::Digits4);

    str comp2 = this.TableId == tableNum(SalesTable) ? this.CustomerAccount : this.InventLocationTo;

    return strFmt("@MET:ShipmentStrFmt", 
        this.InventLocationFrom, 
        comp2,
        this.getRoute(), 
        shippingDateStr);
}

/// <summary>
///
/// </summary>
public METRoute getRoute()
{
    METRoute route;

    if(this.TableId == tableNum(SalesTable))
    {
        route = this.Route;
    }
    else if(this.TableId == tableNum(InventTransferTable))
    {
        route = METInventTransferTableExt::findByTransferId(this.OrderId).Route;
    }

    return route;
}

/// <summary>
/// Validate if Sales order excluded from TMS engine
/// </summary>
/// <returns>
/// a boolean value<c>boolean</c> query.
/// </returns>
public boolean isOrderExcluded()
{
    METSalesOrderTypes  salesOrderTypes;
    boolean             ret = false;

    if(this.TableId == tableNum(SalesTable))
    {
        salesOrderTypes = METSalesOrderTypes::find(this.OrderType);

        if (salesOrderTypes.RecId)
        {
            ret = salesOrderTypes.ExcludeFromTMSEngine;
        }
    }
    else if(this.TableId == tableNum(InventTransferTable))
    {
        ret = false;
    }

    return ret;
}

/// <summary>
///
/// </summary>
public TransDate getShipDate()
{
    TransDate shipDate;

    shipDate = this.ConfirmedShipDate;

    if(this.TableId == tableNum(SalesTable) && !shipDate)
    {
        shipDate = this.RequestedShipDate;
    }

    return shipDate;
}

public TransDate getReceiptDate()
{
    TransDate receiptDate;

    receiptDate = this.ConfirmedReceiptDate;

    if(this.TableId == tableNum(SalesTable) && !receiptDate)
    {
        receiptDate = this.RequestedReceiptDate;
    }

    return receiptDate;
}

/// <summary>
/// Get the destination type of the shipment.
/// </summary>
/// <returns>Customer if this a sales, otherwise warehouse</returns>
public METDestinationType getDestinationType()
{
    METDestinationType ret;

    if(this.TableId == tableNum(SalesTable))
    {
        ret = METDestinationType::Customer;
    }
    else if(this.TableId == tableNum(InventTransferTable))
    {
        ret = METDestinationType::Warehouse;
    }

    return ret;
}

/// <summary>
///
/// </summary>
public METRouteStopNum getRouteStop()
{
    METRouteStopNum routeStop = this.RouteStop;

    if(!routeStop && this.TableId == tableNum(InventTransferTable))
    {
        routeStop = METInventTransferTableExt::findByTransferId(this.OrderId).RouteStopNum;
    }

    return routeStop;
}
